presets.read:
?subject ?flag ?property .
OPTIONAL {
  ?ax owl:annotatedSource ?subject ;
      owl:annotatedProperty ?flag ;
      owl:annotatedTarget ?property .
  OPTIONAL { ?ax :editedBy ?user }
  OPTIONAL { ?ax :editedAt ?time }
}

presets.declarations:
:editedBy a owl:AnnotationProperty ;
    rdfs:label "edited by"@en ;
    rdfs:comment "Identifier of the user who entered or edited the field referenced by a :userEdited assertion."@en ;
    rdfs:range xsd:string .
:editedAt a owl:AnnotationProperty ;
    rdfs:label "edited at"@en ;
    rdfs:comment "Timestamp of the user edit referenced by a :userEdited assertion."@en ;
    rdfs:range xsd:dateTime .

presets.write:
?subject ?flag ?property .
?userIri a :User ; :userId ?user .
[] a owl:Axiom ;
   owl:annotatedSource   ?subject ;
   owl:annotatedProperty ?flag ;
   owl:annotatedTarget   ?property ;
   :editedBy ?userIri ;
   :editedAt ?time .

presets.read:
?subject ?flag ?property .
OPTIONAL {
  ?ax owl:annotatedSource ?subject ;
      owl:annotatedProperty ?flag ;
      owl:annotatedTarget ?property .
  OPTIONAL { ?ax :editedBy ?u . OPTIONAL { ?u :userId ?uid } }
  OPTIONAL { ?ax :editedAt ?time }
}
BIND(COALESCE(?uid, ?u) AS ?user)

?st a rdf:Statement ;
    rdf:subject ?subject ;
    rdf:predicate ?property .
OPTIONAL { ?st :editedBy ?user }
OPTIONAL { ?st :editedAt ?time }
